    public static class TestClass implements Serializable {
        public String value = "original";
    }

    public static class NonSerializableClass {
        public String value = "original";
    }









    @Test
    public void testCreateMock_ValidationFailure() {
        MockSettingsImpl settings = new MockSettingsImpl();
        doThrow(new RuntimeException("Validation Failed")).when(creationValidator).validateType(anyClass());

        try {
            mockUtil.createMock(TestClass.class, settings);
        } catch (RuntimeException e) {
            assertEquals("Validation Failed", e.getMessage());
        }
    }





    // Helper for generic type validation testing
    private <T> Class<T> anyClass() {
        return (Class<T>) TestClass.class;
